<template><div><div class="head"><div><h2>Agent 运行与评测</h2><p>关注真实工具调用、响应延迟和模型降级，而不是只看聊天效果。</p></div><el-button :loading="loading" @click="load">刷新指标</el-button></div><div class="cards"><el-card v-for="item in items" :key="item.key" shadow="never"><small>{{item.name}}</small><strong>{{format(item)}}</strong><span>{{item.tip}}</span></el-card></div><el-card shadow="never"><template #header><b>质量门槛</b></template><el-descriptions :column="1" border><el-descriptions-item label="工具可追溯">每条 Agent 回复记录工具名称、结果、模型来源和耗时</el-descriptions-item><el-descriptions-item label="失败可降级">模型不可用时仍可完成课程检索与计划进度查询</el-descriptions-item><el-descriptions-item label="高风险确认">计划启用需要用户确认，Agent 不自动发起付费与选课</el-descriptions-item><el-descriptions-item label="数据隔离">会话、计划和任务均按登录用户校验归属</el-descriptions-item></el-descriptions></el-card></div></template>
<script setup>import{computed,onMounted,ref}from'vue';import{adminApi}from'@/api/admin';const loading=ref(false),data=ref({});const defs=[['conversations','会话数','持久化 Agent 会话'],['messages','消息数','用户与 Agent 消息'],['toolCalls','工具调用','真实业务工具执行'],['fallbackRate','降级率','模型不可用时占比','%'],['averageLatencyMs','平均延迟','Agent 单次响应耗时',' ms']];const items=computed(()=>defs.map(([key,name,tip,unit=''])=>({key,name,tip,unit,value:data.value[key]??0})));const format=i=>`${i.value}${i.unit}`;async function load(){loading.value=true;try{data.value=(await adminApi.getAgentMetrics()).data||{}}finally{loading.value=false}}onMounted(load)</script>
<style scoped>.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.head h2{margin:0 0 8px}.head p{margin:0;color:#7b8798}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:15px;margin-bottom:20px}.cards :deep(.el-card__body){display:flex;flex-direction:column;gap:9px}.cards small,.cards span{color:#8491a4}.cards strong{font-size:28px;color:#123f63}@media(max-width:1000px){.cards{grid-template-columns:repeat(2,1fr)}}</style>
